static int gGarageSel = 0; static float gGarageRot = 0; static int gGarageTab = 0, gPlateSel = 0;
// номер в интерфейсе: синяя полицейская табличка
static void drawPlateUI(float x, float y, float w, const PlateOffer& o) {
    float h = w * 0.215f, u = U();
    UI.roundRect(x, y, w, h, h * 0.12f, RGBA(15, 15, 15));
    UI.roundRect(x + h * 0.06f, y + h * 0.06f, w - h * 0.12f, h * 0.88f, h * 0.1f, RGBA(30, 70, 170));
    float sx = x + w * 0.78f;
    UI.rect(sx, y + h * 0.1f, std::max(1.f, u * 0.3f), h * 0.8f, C_WHITE);
    UI.text(x + w * 0.39f, y + h * 0.2f, o.num, h * 0.068f * 9.5f / 9.5f, C_WHITE, 1, true);
    UI.text(sx + w * 0.11f, y + h * 0.1f, fmt("%d", o.region).c_str(), h * 0.042f * 9.5f / 9.5f, C_WHITE, 1, true);
    UI.text(sx + w * 0.11f, y + h * 0.62f, "RUS", h * 0.022f * 9.5f / 9.5f, C_WHITE, 1);
}
static void drawGarage(float dt) {
    float u = U();
    gGarageRot += dt * 0.5f;
    // 3D-превью
    Lighting saved = L;
    updateLighting(15.5f, 0);
    L.fogStart = 200; L.fogEnd = 400; L.hlOn = 0;
    UI.rectG(0, 0, SW, SH, RGBA(40, 50, 70), RGBA(15, 18, 26));
    UI.flush();
    const CarModel& MM = CM[PATROL[gGarageSel].model];
    float camD = 6.5f + MM.halfL * 1.6f;
    V3 tgt(0, MM.height * 0.45f, 0);
    V3 cp(sinf(gGarageRot) * camD, 2.2f + MM.height * 0.5f, cosf(gGarageRot) * camD);
    V3 dd = tgt - cp;
    R3.setCamera(cp, atan2f(dd.x, dd.z), atan2f(dd.y, sqrtf(dd.x * dd.x + dd.z * dd.z)), 42);
    // смещение влево: камера смотрит немного вправо
    R3.cx = SW * 0.3f;
    // пол
    for (int i = 0; i < 24; i++) {
        float a0 = i * 2 * PI / 24, a1 = (i + 1) * 2 * PI / 24;
        R3.triW(V3(0, 0, 0), V3(cosf(a0) * 4.2f, 0, sinf(a0) * 4.2f), V3(cosf(a1) * 4.2f, 0, sinf(a1) * 4.2f), RGBA(60, 66, 78), 0);
    }
    const CarModel& M = CM[PATROL[gGarageSel].model];
    R3.groundSprite(V3(0, 0.02f, (M.maxZ + M.minZ) * 0.5f), V3(M.halfW * 1.4f, 0, 0), V3(0, 0, M.halfL * 1.2f), RGBA(0, 0, 0, 170), 0, 0);
    DrawCar d; d.pos = V3(0, 0, 0); d.yaw = 0; d.police = true; d.flash = true; d.time = gTime; d.paint = Col(0.95f, 0.95f, 0.96f); d.plate = 2; d.spin = gTime;
    drawCarModel(PATROL[gGarageSel].model, d);
    R3.draw();
    L = saved;
    float mx = std::max(SW * 0.035f, 16.0f), mt = SH * 0.04f;
    UI.text(mx, mt, "ГАРАЖ", u * 2.2f, C_WHITE, 0, true);
    UI.text(mx, mt + u * 20, fmt("%d ₽   %s", SV.money, RANKS[rankOf(SV.rep)]).c_str(), u * 1.1f, C_YELLOW, 0, true);
    const PatrolSpec& ps = PATROL[gGarageSel];
    float iy = SH * 0.76f;
    UI.text(SW * 0.3f, iy, ps.name, u * 1.8f, C_WHITE, 1, true);
    UI.text(SW * 0.3f, iy + u * 39, carTitle(ps.model).c_str(), u * 0.95f, C_YELLOW, 1, true);
    UI.text(SW * 0.3f, iy + u * 17, ps.desc, u * 0.85f, C_LIGHT, 1, true);
    UI.text(SW * 0.3f, iy + u * 28, fmt("МАКС. %d КМ/Ч    МАССА %.1f", (int)(ps.vmax * (1 + 0.07f * SV.upg[U_ENGINE])), ps.mass).c_str(), u * 0.9f, RGBA(150, 200, 255), 1, true);
    // список машин
    float px = SW * 0.58f, pw = SW - px - mx;
    float y = mt;
    // вкладки: машины / номера
    {
        float tw = (pw - u * 3) * 0.5f;
        if (button(px, y, tw, u * 16, "МАШИНЫ", gGarageTab == 0 ? C_BLUE : C_GRAY, u * 0.9f)) { gGarageTab = 0; applyPlayerPlate(SV.plate); }
        if (button(px + tw + u * 3, y, tw, u * 16, "НОМЕРА", gGarageTab == 1 ? C_BLUE : C_GRAY, u * 0.9f)) { gGarageTab = 1; gPlateSel = SV.plate; }
        y += u * 20;
    }
    if (gGarageTab == 1) {
        // красивые номера: превью на машине — выбранный в списке
        applyPlayerPlate(gPlateSel);
        float cw2 = (pw - u * 3) * 0.5f, bh = u * 22;
        for (int k = 0; k < PLATE_SHOP_N; k++) {
            const PlateOffer& o = PLATE_SHOP[k];
            bool owned = (SV.platesOwned >> k) & 1;
            float bx = px + (k % 2) * (cw2 + u * 3), by = y + (k / 2) * (bh + u * 2);
            if (button(bx, by, cw2, bh, "", k == gPlateSel ? C_BLUE : C_GRAY, u * 0.8f)) gPlateSel = k;
            drawPlateUI(bx + u * 3, by + u * 3, cw2 * 0.5f, o);
            std::string sub = owned ? (SV.plate == k ? "НА МАШИНЕ" : "КУПЛЕН") : fmt("%d ₽", o.price);
            SDL_Color sc = owned ? RGBA(140, 230, 150) : (rankOf(SV.rep) >= o.rank ? C_YELLOW : RGBA(255, 140, 130));
            UI.text(bx + cw2 * 0.77f, by + u * 3, sub.c_str(), u * 0.7f, sc, 1);
            UI.text(bx + cw2 * 0.77f, by + u * 12, o.tag, u * 0.55f, RGBA(170, 180, 195), 1);
        }
        y += ((PLATE_SHOP_N + 1) / 2) * (bh + u * 2) + u * 4;
        const PlateOffer& o = PLATE_SHOP[gPlateSel];
        bool owned = (SV.platesOwned >> gPlateSel) & 1;
        if (owned) {
            if (SV.plate != gPlateSel) { if (button(px, y, pw, u * 20, "ПОСТАВИТЬ НА МАШИНУ", C_GREEN, u * 1.0f)) { SV.plate = gPlateSel; sfx(SFX_CLICK); saveGame(); } }
            else UI.text(px + pw / 2, y + u * 6, "ЭТОТ НОМЕР УЖЕ НА ПАТРУЛЬНОЙ МАШИНЕ", u * 0.85f, RGBA(140, 230, 150), 1);
        } else if (rankOf(SV.rep) < o.rank) UI.text(px + pw / 2, y + u * 6, fmt("НУЖНО ЗВАНИЕ: %s", RANKS[o.rank]).c_str(), u * 0.9f, RGBA(255, 130, 120), 1);
        else if (button(px, y, pw, u * 20, fmt("КУПИТЬ ЗА %d ₽", o.price).c_str(), C_GREEN, u * 1.0f, SV.money >= o.price)) {
            SV.money -= o.price; SV.platesOwned |= 1 << gPlateSel; SV.plate = gPlateSel; sfx(SFX_COIN); saveGame();
        }
        y += u * 26;
        UI.text(px, y, "НОМЕР ОДИН НА ВСЕ МАШИНЫ ГАРАЖА.", u * 0.7f, RGBA(150, 160, 175));
        if (button(mx, SH - mt - u * 24, u * 90, u * 24, "НАЗАД", C_GRAY, u * 1.2f) || gBackPressed) { gBackPressed = false; applyPlayerPlate(SV.plate); gScreen = SC_MENU; }
        return;
    }
    {   // две колонки по 4 машины
        float cw2 = (pw - u * 3) * 0.5f;
        for (int k = 0; k < PATROL_N; k++) {
            int i = PATROL_ORDER[k];
            const PatrolSpec& s = PATROL[i];
            bool owned = (SV.carOwned >> i) & 1;
            std::string sub = owned ? (SV.car == i ? "ВЫБРАНА" : "КУПЛЕНА") : fmt("%d ₽", s.price);
            float bx = px + (k % 2) * (cw2 + u * 3), by = y + (k / 2) * u * 21;
            if (button(bx, by, cw2, u * 19, "", i == gGarageSel ? C_BLUE : C_GRAY, u * 0.8f)) gGarageSel = i;
            UI.text(bx + cw2 / 2, by + u * 2.5f, std::string(s.name).c_str(), u * 0.75f, C_WHITE, 1);
            UI.text(bx + cw2 / 2, by + u * 11, sub.c_str(), u * 0.7f, owned ? RGBA(140, 230, 150) : (rankOf(SV.rep) >= s.rank ? C_YELLOW : RGBA(255, 140, 130)), 1);
        }
        y += u * 21 * ((PATROL_N + 1) / 2) + u * 2;
    }
    {
        const PatrolSpec& s = PATROL[gGarageSel];
        bool owned = (SV.carOwned >> gGarageSel) & 1;
        bool rankOk = rankOf(SV.rep) >= s.rank;
        if (owned) { if (SV.car != gGarageSel && button(px, y, pw, u * 20, "ВЫБРАТЬ", C_GREEN, u * 1.1f)) { SV.car = gGarageSel; saveGame(); } }
        else if (!rankOk) { UI.text(px + pw / 2, y + u * 6, fmt("НУЖНО ЗВАНИЕ: %s", RANKS[s.rank]).c_str(), u * 0.9f, RGBA(255, 130, 120), 1); }
        else if (button(px, y, pw, u * 20, fmt("КУПИТЬ ЗА %d ₽", s.price).c_str(), C_GREEN, u * 1.1f, SV.money >= s.price)) { SV.money -= s.price; SV.carOwned |= 1 << gGarageSel; SV.car = gGarageSel; sfx(SFX_COIN); saveGame(); }
        y += u * 26;
    }
    UI.text(px, y, "УЛУЧШЕНИЯ (ДЛЯ ВСЕХ МАШИН)", u * 1.0f, RGBA(150, 200, 255)); y += u * 12;
    for (int k = 0; k < U_COUNT; k++) {
        int lv = SV.upg[k];
        UI.text(px, y + u * 2, UPG_NAMES[k], u * 0.95f, C_WHITE);
        UI.text(px, y + u * 11, UPG_DESC[k], u * 0.7f, RGBA(150, 160, 175));
        for (int p = 0; p < 3; p++) UI.rect(px + pw * 0.45f + p * u * 9, y + u * 4, u * 7, u * 7, p < lv ? C_YELLOW : RGBA(60, 66, 76));
        if (lv < 3) { if (button(px + pw * 0.66f, y, pw * 0.34f, u * 17, fmt("%d ₽", UPG_PRICE[k][lv]).c_str(), C_GREEN, u * 0.9f, SV.money >= UPG_PRICE[k][lv])) { SV.money -= UPG_PRICE[k][lv]; SV.upg[k]++; sfx(SFX_COIN); saveGame(); } }
        else UI.text(px + pw * 0.83f, y + u * 5, "МАКС.", u * 0.9f, C_YELLOW, 1);
        y += u * 21;
    }
    if (button(mx, SH - mt - u * 24, u * 90, u * 24, "НАЗАД", C_GRAY, u * 1.2f) || gBackPressed) { gBackPressed = false; gScreen = SC_MENU; }
}

// ---------------------------------------------------------------------
//  Меню, начало смены, пауза, итоги, памятка
// ---------------------------------------------------------------------
static float gMenuOrbit = 0;
static void drawMenuScene(float dt) {
    // фоновая сцена: патрульная машина у поста
    gMenuOrbit += dt * 0.08f;
    gWorldTime += dt;
    updateLighting(18.6f, 0);
    const Post& P = POSTS[0];
    PL.pos = P.pos; PL.yaw = P.yaw; PL.flash = true; PL.speed = 0; PL.spec = SV.car;
    V3 c = P.pos + V3(0, 0.8f, 0);
    V3 cam = c + V3(sinf(gMenuOrbit) * 9, 2.4f, cosf(gMenuOrbit) * 9);
    V3 d = c - cam;
    R3.setCamera(cam, atan2f(d.x, d.z), atan2f(d.y, sqrtf(d.x * d.x + d.z * d.z)), 60);
    if (CARS.empty()) for (int i = 0; i < 14; i++) spawnTrafficCar(P.pos, 20, 300, false);
    updateTraffic(dt, true);
    updatePeds(dt, P.pos, true);
    updateParts(dt);
    drawWorldScene(dt, true, false);
}
// ---------------------------------------------------------------------
//  Заставка при запуске: мигалка в темноте со звуком -> уезжает вверх -> название игры
// ---------------------------------------------------------------------
static float gIntroT = 0, gFadeIn = 0;
static bool gIntroSkip = false;
static bool gIntroQuack = false, gIntroThunk = false;
// сброс заставки при каждом показе: остатки событий прошлого запуска не должны её пропускать
static void startIntro() {
    gScreen = SC_INTRO; gIntroT = 0; gIntroSkip = false; gBackPressed = false;
    gIntroQuack = gIntroThunk = false; TAPS.clear(); SY.siren = 0;
}
static void introLightbar(float cx, float cy, float bw, float bh, bool redOn, bool blueOn, float u) {
    float bx = cx - bw / 2, by = cy - bh / 2, r = bh * 0.28f;
    UI.roundRect(bx + u * 3, by + u * 4, bw, bh, r, RGBA(0, 0, 0, 120));               // тень
    UI.roundRect(bx - u * 2, by - u * 2, bw + u * 4, bh + u * 4, r + u, RGBA(70, 72, 80));   // хромированная окантовка
    UI.roundRect(bx, by, bw, bh, r, RGBA(28, 30, 35));
    float cw = bw * 0.17f, lw = (bw - cw) / 2 - u * 6, ly = by + u * 4, lh = bh - u * 8;
    for (int side = 0; side < 2; side++) {
        bool on = side == 0 ? redOn : blueOn;
        float lx = side == 0 ? bx + u * 4 : cx + cw / 2 + u * 2;
        SDL_Color off = side == 0 ? RGBA(85, 12, 14) : RGBA(12, 22, 90);
        SDL_Color lit = side == 0 ? RGBA(255, 45, 35) : RGBA(40, 90, 255);
        SDL_Color hot = side == 0 ? RGBA(255, 190, 170) : RGBA(190, 215, 255);
        UI.roundRect(lx, ly, lw, lh, r * 0.6f, on ? lit : off);
        // светодиоды: в каждой секции 3×2
        for (int k = 0; k < 3; k++) for (int c2 = 0; c2 < 3; c2++) for (int r2 = 0; r2 < 2; r2++) {
            float ex = lx + lw * k / 3 + lw / 3 * (c2 + 0.5f) / 3, ey = ly + lh * (r2 == 0 ? 0.34f : 0.68f), er = lh * 0.11f;
            if (on) { UI.glow(ex, ey, er * 3.2f, RGBA(hot.r, hot.g, hot.b, 120)); UI.circle(ex, ey, er, hot, 12); }
            else UI.circle(ex, ey, er, RGBA(off.r / 2 + 10, off.g / 2 + 8, off.b / 2 + 10), 12);
        }
        for (int k = 1; k < 3; k++) UI.rect(lx + lw * k / 3 - u * 0.7f, ly, u * 1.4f, lh, RGBA(20, 20, 24, 200));   // перегородки
        UI.rectG(lx + u * 2, ly + u * 1.5f, lw - u * 4, lh * 0.28f, RGBA(255, 255, 255, on ? 90 : 35), RGBA(255, 255, 255, 0));   // блик на стекле
    }
    // центральный модуль с надписью
    UI.roundRect(cx - cw / 2, ly, cw, lh, u * 3, RGBA(225, 228, 232));
    UI.text(cx, ly + lh / 2 - bh * 0.13f, "ДПС", bh * 0.035f, RGBA(25, 60, 170), 1);
}
static void drawIntro(float dt) {
    float u = U();
    gIntroT += dt; float t = gIntroT;
    const float SLIDE0 = 2.3f, SLIDE1 = 3.05f, TITLE0 = 2.85f, END = 5.4f;
    if (t < 0.6f) { gIntroSkip = false; gBackPressed = false; TAPS.clear(); }   // первые 0.6 с ввод игнорируем
    else if (gIntroSkip || !TAPS.empty() || gBackPressed) {   // пропуск — сразу в меню
        gIntroSkip = false; gBackPressed = false; TAPS.clear();
        SY.siren = 0; gScreen = SC_MENU; gFadeIn = 0.5f; return;
    }
    // звук: «кряк», затем вой сирены, пока мигалка на экране
    if (t > 0.12f && !gIntroQuack) { gIntroQuack = true; sfx(SFX_QUACK, 0.9f); }
    SY.engVol = 0; SY.engLoad = 0; SY.wind = 0; SY.screech = 0; SY.rain = 0; SY.ambient = 0;
    SY.siren = (t > 0.45f && t < SLIDE1 + 0.1f) ? 1.f : 0.f;
    // фон: ночь
    UI.rectG(0, 0, SW, SH, RGBA(6, 8, 16), RGBA(14, 16, 26));
    // мигание «полицейское»: три быстрые вспышки красным, потом три синим
    float ph = fmodf(t, 0.9f);
    bool redOn = ph < 0.45f && fmodf(ph, 0.15f) < 0.09f, blueOn = ph >= 0.45f && fmodf(ph - 0.45f, 0.15f) < 0.09f;
    if (t < 0.25f) redOn = blueOn = false;
    // положение мигалки: стоит по центру, затем разгоняется вверх за экран
    float bw = std::min(SW * 0.72f, SH * 1.8f), bh = bw * 0.18f;
    float k = clampf((t - SLIDE0) / (SLIDE1 - SLIDE0), 0, 1), e = k * k * (1.6f - 0.6f * k);
    float cy = SH * 0.46f - e * (SH * 0.46f + bh * 1.5f);
    float wash = 1 - clampf((t - SLIDE0 - 0.3f) / 1.0f, 0, 1);   // заливка светом слабеет, когда мигалка уходит
    if (redOn) {
        UI.rectGH(0, 0, SW, SH, RGBA(210, 20, 25, (int)(95 * wash)), RGBA(210, 20, 25, 0));
        UI.glow(SW / 2 - bw * 0.27f, cy, bw * 0.55f, RGBA(255, 40, 30, (int)(170 * std::max(wash, 0.35f))));
    }
    if (blueOn) {
        UI.rectGH(0, 0, SW, SH, RGBA(25, 60, 255, 0), RGBA(25, 60, 255, (int)(95 * wash)));
        UI.glow(SW / 2 + bw * 0.27f, cy, bw * 0.55f, RGBA(40, 90, 255, (int)(170 * std::max(wash, 0.35f))));
    }
    if (cy > -bh * 1.2f) introLightbar(SW / 2, cy, bw, bh, redOn, blueOn, u);
    // название
    if (t > TITLE0) {
        if (!gIntroThunk) { gIntroThunk = true; sfx(SFX_THUNK, 0.7f); }
        float a = clampf((t - TITLE0) / 0.55f, 0, 1), ea = 1 - (1 - a) * (1 - a);
        float sc = 1.22f - 0.22f * ea;
        int al = (int)(255 * ea);
        float ty = SH * 0.33f;
        // отсветы мигалки по краям, затухают
        float rem = clampf(1 - (t - TITLE0) / 1.6f, 0, 1);
        if (redOn) UI.glow(SW * 0.12f, ty + u * 30, SW * 0.3f, RGBA(255, 40, 30, (int)(110 * rem)));
        if (blueOn) UI.glow(SW * 0.88f, ty + u * 30, SW * 0.3f, RGBA(40, 90, 255, (int)(110 * rem)));
        UI.text(SW / 2, ty, "ИНСПЕКТОР", u * 5.2f * sc, RGBA(255, 255, 255, al), 1, true);
        UI.text(SW / 2, ty + u * 46 * sc, "ДПС", u * 5.2f * sc, RGBA(80, 140, 255, al), 1, true);
        float lineK = clampf((t - TITLE0 - 0.35f) / 0.5f, 0, 1), lw = u * 190 * (1 - (1 - lineK) * (1 - lineK));
        UI.rect(SW / 2 - lw / 2, ty + u * 92, lw, u * 3.5f, RGBA(220, 40, 40, al));
        float st = clampf((t - TITLE0 - 0.8f) / 0.6f, 0, 1);
        UI.text(SW / 2, ty + u * 102, "ПАТРУЛЬНАЯ СЛУЖБА", u * 1.3f, RGBA(200, 205, 215, (int)(255 * st)), 1, true);
        // блик, пробегающий по надписи
        float sw = (t - TITLE0 - 0.6f) / 0.9f;
        if (sw > 0 && sw < 1) UI.glow(SW * (0.2f + 0.6f * sw), ty + u * 40, u * 60, RGBA(255, 255, 255, (int)(60 * sinf(sw * PI))));
    }
    // уход в меню
    if (t > END - 0.5f) UI.rect(0, 0, SW, SH, RGBA(0, 0, 0, (int)(255 * clampf((t - (END - 0.5f)) / 0.5f, 0, 1))));
    if (t > END) { SY.siren = 0; gScreen = SC_MENU; gFadeIn = 0.6f; }
    if (t > 1.0f) UI.text(SW - u * 8, SH - u * 12, "НАЖМИ, ЧТОБЫ ПРОПУСТИТЬ", u * 0.8f, RGBA(120, 125, 140, 160), 2);
}
static void drawMenu(float dt) {
    float u = U();
    drawMenuScene(dt);
    UI.rectGH(0, 0, SW * 0.6f, SH, RGBA(0, 0, 0, 190), RGBA(0, 0, 0, 0));
    float mx = std::max(SW * 0.05f, 16.0f);
    UI.text(mx, SH * 0.1f, "ИНСПЕКТОР", u * 4.2f, C_WHITE, 0, true);
    UI.text(mx, SH * 0.1f + u * 34, "ДПС", u * 4.2f, RGBA(80, 140, 255), 0, true);
    UI.rect(mx, SH * 0.1f + u * 68, u * 150, u * 3, C_RED);
    UI.text(mx, SH * 0.1f + u * 76, fmt("СМЕНА №%d   %s", SV.day, dateStr(TODAY()).c_str()).c_str(), u * 1.1f, C_LIGHT, 0, true);
    UI.text(mx, SH * 0.1f + u * 88, fmt("%s   РЕПУТАЦИЯ %d   %d ₽", RANKS[rankOf(SV.rep)], SV.rep, SV.money).c_str(), u * 1.1f, C_YELLOW, 0, true);
    float bw = u * 150, bh = u * 25, bx = mx, by = SH * 0.48f;
    if (button(bx, by, bw, bh, "НАЧАТЬ СМЕНУ", C_BLUE, u * 1.3f)) {
        gScreen = SC_SHIFTSTART; { int yy, mm, dd; civilFromDays(TODAY(), yy, mm, dd); bool winter = mm >= 11 || mm <= 3; float wr = grng.f();
          gPlannedWeather = winter ? (wr < 0.3f ? 0 : (wr < 0.5f ? 1 : 3)) : (wr < 0.5f ? 0 : (wr < 0.75f ? 1 : 2)); } gPlannedNight = false;
        gPlannedDistrict = std::min(SV.lastDistrict, 3); if (rankOf(SV.rep) < DISTRICT_RANK[gPlannedDistrict]) gPlannedDistrict = 0;
    }
    by += bh + u * 6;
    if (button(bx, by, bw, bh, "ГАРАЖ", C_GRAY, u * 1.2f)) { gScreen = SC_GARAGE; gGarageSel = SV.car; }
    by += bh + u * 6;
    if (button(bx, by, bw, bh, "КАМЕРЫ НА КАРТЕ", C_GRAY, u * 1.2f)) { gMapReturn = SC_MENU; gScreen = SC_MAP; }
    by += bh + u * 6;
    if (button(bx, by, bw * 0.48f, bh, "ПАМЯТКА", C_GRAY, u * 1.0f)) { gHelpReturn = SC_MENU; gScreen = SC_HELP; }
    if (button(bx + bw * 0.52f, by, bw * 0.48f, bh, "НАСТРОЙКИ", C_GRAY, u * 1.0f)) { gSettingsReturn = SC_MENU; gScreen = SC_SETTINGS; }
    by += bh + u * 6;
    if (button(bx, by, bw, bh * 0.85f, "ВЫХОД", RGBA(110, 40, 40), u * 1.1f) || gBackPressed) { gBackPressed = false; gScreen = SC_EXITCONFIRM; }
    SY.engVol = 0.3f; SY.engRpm = 0.12f; SY.engLoad = 0; SY.siren = 0; SY.rain = 0; SY.ambient = 0.15f; SY.screech = 0; SY.wind = 0;
}
static void drawExitConfirm(float dt) {
    float u = U();
    drawMenuScene(dt);
    UI.rect(0, 0, SW, SH, RGBA(0, 0, 0, 160));
    panel(SW / 2 - u * 100, SH / 2 - u * 40, u * 200, u * 80, C_DARK);
    UI.text(SW / 2, SH / 2 - u * 30, "ВЫЙТИ ИЗ ИГРЫ?", u * 1.4f, C_WHITE, 1);
    if (button(SW / 2 - u * 90, SH / 2 + u * 5, u * 85, u * 26, "ДА", C_RED, u * 1.2f)) { saveGame(); gQuit = true; }
    if (button(SW / 2 + u * 5, SH / 2 + u * 5, u * 85, u * 26, "НЕТ", C_GRAY, u * 1.2f) || gBackPressed) { gBackPressed = false; gScreen = SC_MENU; }
}
static void drawShiftStart(float dt) {
    float u = U();
    drawMenuScene(dt);
    UI.rect(0, 0, SW, SH, RGBA(0, 0, 0, 150));
    float mx = std::max(SW * 0.05f, 16.0f), mt = SH * 0.05f;
    float W = SW - 2 * mx;
    panel(mx, mt, W, SH - 2 * mt, C_DARK);
    UI.text(mx + u * 10, mt + u * 8, fmt("ЗАСТУПЛЕНИЕ НА СМЕНУ №%d  —  %s", SV.day, dateStr(TODAY()).c_str()).c_str(), u * 1.4f, C_WHITE);
    float y = mt + u * 28, cw = W * 0.48f;
    UI.text(mx + u * 10, y, "СМЕНА", u * 1.0f, RGBA(150, 200, 255)); y += u * 11;
    if (button(mx + u * 10, y, cw * 0.48f, u * 22, "ДНЕВНАЯ 08–16", !gPlannedNight ? C_BLUE : C_GRAY, u * 1.0f)) gPlannedNight = false;
    if (button(mx + u * 14 + cw * 0.48f, y, cw * 0.48f, u * 22, "НОЧНАЯ 20–04", gPlannedNight ? C_BLUE : C_GRAY, u * 1.0f)) gPlannedNight = true;
    y += u * 28;
    static const char* wnames[] = {"ЯСНО", "ПАСМУРНО", "ДОЖДЬ", "СНЕГОПАД, ГОЛОЛЁД"};
    UI.text(mx + u * 10, y + u * 3, "ПОГОДА:", u * 1.1f, C_YELLOW);
    if (button(mx + u * 10 + UI.textW("ПОГОДА: ", u * 1.1f), y, cw * 0.62f, u * 16, wnames[gPlannedWeather], gPlannedWeather == 3 ? RGBA(90, 130, 190) : C_GRAY, u * 0.9f)) gPlannedWeather = (gPlannedWeather + 1) % 4;
    y += u * 20;
    UI.text(mx + u * 10, y, "ПАТРУЛЬНАЯ МАШИНА: ", u * 1.0f, RGBA(150, 200, 255));
    UI.text(mx + u * 10 + UI.textW("ПАТРУЛЬНАЯ МАШИНА: ", u), y, PATROL[SV.car].name, u * 1.0f, C_WHITE); y += u * 16;
    UI.text(mx + u * 10, y, "ЗАДАНИЯ ВЫДАЮТСЯ ПРИ ЗАСТУПЛЕНИИ.", u * 0.9f, C_LIGHT); y += u * 11;
    UI.text(mx + u * 10, y, "ДЛИТЕЛЬНОСТЬ СМЕНЫ ~12 МИНУТ.", u * 0.9f, C_LIGHT);
    // участки
    float rx = mx + cw + u * 20, ry = mt + u * 28, rw = W - cw - u * 30;
    UI.text(rx, ry, "УЧАСТОК ПАТРУЛИРОВАНИЯ", u * 1.0f, RGBA(150, 200, 255)); ry += u * 11;
    for (int d = 0; d < 4; d++) {
        bool ok = rankOf(SV.rep) >= DISTRICT_RANK[d];
        float lv0 = DISTRICT_TRAFFIC[d] * hourTraffic(gPlannedNight ? 20 * 60 + 30 : 8 * 60 + 30);
        float pm0 = clampf(roundf((0.5f + 0.62f * lv0) * 20) / 20, 0.75f, 1.8f);
        std::string l = ok ? fmt("%s — ТРАФИК %s, ДОХОД X%.2f", DISTRICT_NAMES[d], trafficName(lv0), pm0) : std::string(DISTRICT_NAMES[d]) + " (С ЗВАНИЯ " + RANKS[DISTRICT_RANK[d]] + ")";
        if (button(rx, ry, rw, u * 21, l.c_str(), gPlannedDistrict == d ? C_BLUE : C_GRAY, u * 0.95f, ok)) gPlannedDistrict = d;
        ry += u * 25;
    }
    float bh = u * 28;
    if (button(SW - mx - u * 170, SH - mt - bh - u * 8, u * 160, bh, "НА ЛИНИЮ!", C_GREEN, u * 1.4f)) startShift();
    if (button(mx + u * 10, SH - mt - bh - u * 8, u * 100, bh, "НАЗАД", C_GRAY, u * 1.2f) || gBackPressed) { gBackPressed = false; gScreen = SC_MENU; }
}
static void drawPause() {
    float u = U();
    UI.rect(0, 0, SW, SH, RGBA(0, 0, 0, 160));
    float w = u * 190, h = u * 190, x = SW / 2 - w / 2, y = SH / 2 - h / 2;
    panel(x, y, w, h, C_DARK);
    UI.text(SW / 2, y + u * 8, "ПАУЗА", u * 1.8f, C_WHITE, 1);
    float by = y + u * 32, bh = u * 24;
    if (button(x + u * 10, by, w - u * 20, bh, "ПРОДОЛЖИТЬ", C_BLUE, u * 1.2f) || gBackPressed) { gBackPressed = false; gScreen = SC_DRIVE; }
    by += bh + u * 6;
    if (button(x + u * 10, by, w - u * 20, bh, "КАРТА И КАМЕРЫ", C_GRAY, u * 1.1f)) { gMapReturn = SC_PAUSE; gScreen = SC_MAP; TOASTS.clear(); }
    by += bh + u * 6;
    if (button(x + u * 10, by, w - u * 20, bh, "ПАМЯТКА", C_GRAY, u * 1.1f)) { gHelpReturn = SC_PAUSE; gScreen = SC_HELP; }
    by += bh + u * 6;
    if (button(x + u * 10, by, (w - u * 24) / 2, bh, "НАСТРОЙКИ", C_GRAY, u * 1.0f)) { gSettingsReturn = SC_PAUSE; gScreen = SC_SETTINGS; }
    if (button(x + u * 14 + (w - u * 24) / 2, by, (w - u * 24) / 2, bh, "ЗАКОНЧИТЬ", RGBA(150, 50, 40), u * 1.0f)) { endShift(); }
    SY.engVol = 0; SY.siren = 0; SY.screech = 0; SY.wind = 0;
}

// ---------------------------------------------------------------------
//  Настройки управления
// ---------------------------------------------------------------------
static float slider(float x, float y, float w, float h, const char* label, const std::string& valText, float v, float lo, float hi) {
    float u = U();
    UI.text(x, y - u * 11, label, u * 1.0f, C_WHITE);
    UI.text(x + w, y - u * 11, valText.c_str(), u * 1.0f, C_YELLOW, 2);
    for (const Finger& f : FINGERS) if (f.x >= x - u * 10 && f.x <= x + w + u * 10 && f.y >= y - h && f.y <= y + h * 2) v = lo + clampf((f.x - x) / w, 0, 1) * (hi - lo);
    for (Tap& t : TAPS) if (!t.used && t.x >= x - u * 10 && t.x <= x + w + u * 10 && t.y >= y - h && t.y <= y + h * 2) { t.used = true; v = lo + clampf((t.x - x) / w, 0, 1) * (hi - lo); }
    float k = clampf((v - lo) / (hi - lo), 0, 1);
    UI.roundRect(x, y + h * 0.3f, w, h * 0.4f, h * 0.2f, RGBA(60, 66, 78));
    UI.roundRect(x, y + h * 0.3f, std::max(h * 0.4f, w * k), h * 0.4f, h * 0.2f, C_BLUE);
    UI.circle(x + w * k, y + h * 0.5f, h * 0.55f, C_WHITE, 20);
    return v;
}
static float radiusAt(float kmh) {
    const CarModel& M = CM[PATROL[SV.car].model];
    float v = kmh / 3.6f;
    float ms = 0.66f * SV.steerMul / (1 + v * 0.016f);
    float yr = v * tanf(ms) / M.wheelbase;
    float maxLat = 9.81f * specGrip() * 2.6f * SV.gripMul;
    if (yr * v > maxLat) yr = maxLat / v;
    if (SV.gripMul < 0.9f) yr *= 1.0f + (0.9f - SV.gripMul) * 1.6f;
    return v / std::max(yr, 1e-3f);
}
static float accelSteer() {
    if (!gAccel) return 0;
    float a = SDL_JoystickGetAxis(gAccel, 0) / 32767.0f;
    float s = -a * 2.6f * SV.tiltSens;
    if (SV.tiltInv) s = -s;
    if (fabsf(s) < 0.06f) s = 0;
    return clampf(s, -1, 1);
}
// вкладка «Геймпад»: ползунки, переключатели, живой индикатор стика и курков
static void drawPadSettings(float mx, float mt, float W, float H) {
    float u = U();
    float sx = mx + u * 10, sw = W * 0.55f - u * 20, sh = u * 10, sy = mt + u * 46;
    SV.padSteer = slider(sx, sy, sw, sh, "ЧУВСТВИТЕЛЬНОСТЬ РУЛЯ (ЛЕВЫЙ СТИК)", fmt("%d%%", (int)(SV.padSteer * 100 + 0.5f)), SV.padSteer, 0.4f, 2.0f); sy += u * 30;
    SV.padDead = slider(sx, sy, sw, sh, "МЁРТВАЯ ЗОНА СТИКА (ОТ ДРЕЙФА)", fmt("%d%%", (int)(SV.padDead * 100 + 0.5f)), SV.padDead, 0.0f, 0.35f); sy += u * 30;
    SV.padTrig = slider(sx, sy, sw, sh, "ЧУВСТВИТЕЛЬНОСТЬ ГАЗА И ТОРМОЗА (R2/L2)", fmt("%d%%", (int)(SV.padTrig * 100 + 0.5f)), SV.padTrig, 0.4f, 2.0f); sy += u * 30;
    SV.padCursor = slider(sx, sy, sw, sh, "СКОРОСТЬ КУРСОРА", fmt("%d%%", (int)(SV.padCursor * 100 + 0.5f)), SV.padCursor, 0.4f, 2.5f); sy += u * 30;
    float tx = mx + W * 0.58f, tw = W * 0.42f - u * 10, ty = mt + u * 28, th = u * 20;
    if (button(tx, ty, tw, th, SV.padRumble ? "ВИБРАЦИЯ: ВКЛ" : "ВИБРАЦИЯ: ВЫКЛ", SV.padRumble ? C_GREEN : C_GRAY, u * 0.95f)) { SV.padRumble = !SV.padRumble; if (SV.padRumble) padRumble(0.5f, 0.3f, 200); }
    ty += th + u * 4;
    if (button(tx, ty, tw, th, SV.padLed ? "ПОДСВЕТКА DUALSENSE: ВКЛ" : "ПОДСВЕТКА DUALSENSE: ВЫКЛ", SV.padLed ? C_GREEN : C_GRAY, u * 0.95f)) SV.padLed = !SV.padLed;
    ty += th + u * 4;
    if (button(tx, ty, tw, th, SV.padInv ? "ИНВЕРСИЯ РУЛЯ: ВКЛ" : "ИНВЕРСИЯ РУЛЯ: ВЫКЛ", C_GRAY, u * 0.95f)) SV.padInv = !SV.padInv;
    ty += th + u * 9;
    // живая проверка: сырое положение стика и что получит руль
    const char* nm = gPad ? SDL_GameControllerName(gPad) : nullptr;
    UI.text(tx, ty, gPad ? (std::string("ПОДКЛЮЧЁН: ") + (nm && strstr(nm, "DualSense") ? "DUALSENSE" : "ГЕЙМПАД")).c_str() : "ГЕЙМПАД НЕ ПОДКЛЮЧЁН", u * 0.85f, gPad ? RGBA(120, 230, 140) : C_YELLOW);
    ty += u * 12;
    float raw = padAxis(SDL_CONTROLLER_AXIS_LEFTX), out = padStickToSteer(raw);
    auto bar = [&](float y, const char* lb, float v, bool center, SDL_Color c) {
        UI.text(tx, y, lb, u * 0.75f, C_LIGHT);
        float bx = tx + u * 52, bw = tw - u * 52;
        UI.roundRect(bx, y - u * 0.5f, bw, u * 8, u * 2.5f, RGBA(40, 46, 56));
        if (center) {
            UI.rect(bx + bw / 2 - 1, y - u * 0.5f, 2, u * 8, C_LIGHT);
            float x0 = bx + bw / 2, x1 = bx + bw / 2 + v * bw / 2;
            UI.rect(std::min(x0, x1), y + u * 1.5f, fabsf(x1 - x0), u * 4, c);
        } else UI.rect(bx + u, y + u * 1.5f, (bw - u * 2) * clampf(v, 0, 1), u * 4, c);
    };
    // мёртвая зона — тёмные метки на шкале стика
    bar(ty, "СТИК", raw, true, RGBA(150, 160, 175)); {
        float bx = tx + u * 52, bw = tw - u * 52;
        UI.rect(bx + bw / 2 - SV.padDead * bw / 2, ty - u * 0.5f, SV.padDead * bw, u * 8, RGBA(200, 60, 60, 90));
    }
    ty += u * 11;
    bar(ty, "РУЛЬ", out, true, C_YELLOW); ty += u * 11;
    bar(ty, "ГАЗ R2", padTrigger(padAxis(SDL_CONTROLLER_AXIS_TRIGGERRIGHT)), false, RGBA(60, 200, 90)); ty += u * 11;
    bar(ty, "ТОРМОЗ L2", padTrigger(padAxis(SDL_CONTROLLER_AXIS_TRIGGERLEFT)), false, RGBA(220, 70, 70)); ty += u * 13;
    UI.text(tx, ty, "СТИК ДРЕЙФУЕТ — УВЕЛИЧЬ МЁРТВУЮ ЗОНУ.", u * 0.72f, RGBA(150, 160, 175)); ty += u * 9;
    UI.text(tx, ty, "МАШИНУ ВИЛЯЕТ — УМЕНЬШИ ЧУВСТВИТЕЛЬНОСТЬ.", u * 0.72f, RGBA(150, 160, 175));
    if (button(mx + u * 10, mt + H - u * 32, u * 110, u * 24, "СБРОС", RGBA(110, 40, 40), u * 1.1f)) { SV.padSteer = 1; SV.padDead = 0.12f; SV.padTrig = 1; SV.padCursor = 1; SV.padRumble = true; SV.padLed = true; SV.padInv = false; }
    if (button(mx + W - u * 130, mt + H - u * 32, u * 120, u * 24, "ГОТОВО", C_BLUE, u * 1.2f) || gBackPressed) { gBackPressed = false; saveGame(); gScreen = gSettingsReturn; }
    SY.engVol = gSettingsReturn == SC_MENU ? 0.3f : 0; SY.siren = 0; SY.screech = 0; SY.wind = 0;
}
static void drawSettings(float dt) {
    float u = U();
    if (gSettingsReturn == SC_MENU) drawMenuScene(dt);
    else { updateCamera(0, false); drawWorldScene(dt, true, gCamMode == 1); }
    UI.rect(0, 0, SW, SH, RGBA(0, 0, 0, 170));
    float mx = std::max(SW * 0.05f, 16.0f), mt = SH * 0.04f;
    float W = SW - 2 * mx, H = SH - 2 * mt;
    panel(mx, mt, W, H, C_DARK);
    UI.text(mx + u * 10, mt + u * 7, "НАСТРОЙКИ УПРАВЛЕНИЯ", u * 1.6f, C_WHITE);
    static int tab = 0;
    {   // вкладки
        float tw2 = u * 92, tx2 = mx + W - u * 10 - tw2 * 2 - u * 4;
        if (button(tx2, mt + u * 4, tw2, u * 17, "МАШИНА И ЭКРАН", tab == 0 ? C_BLUE : C_GRAY, u * 0.8f)) tab = 0;
        if (button(tx2 + tw2 + u * 4, mt + u * 4, tw2, u * 17, gPad ? "ГЕЙМПАД" : "ГЕЙМПАД (НЕТ)", tab == 1 ? C_BLUE : C_GRAY, u * 0.8f)) tab = 1;
    }
    if (tab == 1) { drawPadSettings(mx, mt, W, H); return; }
    // готовые режимы
    float px = mx + u * 10, py = mt + u * 26, pw = (W * 0.55f - u * 26) / 4, ph = u * 20;
    struct Pre { const char* n; float s, g, sp; };
    static const Pre pres[4] = {{"МЯГКО", 0.8f, 0.9f, 0.75f}, {"ОБЫЧНО", 1.0f, 1.0f, 1.0f}, {"РЕЗКО", 1.35f, 1.35f, 1.5f}, {"ДРИФТ", 1.4f, 0.62f, 1.4f}};
    for (int i = 0; i < 4; i++) {
        bool cur = fabsf(SV.steerMul - pres[i].s) < 0.02f && fabsf(SV.gripMul - pres[i].g) < 0.02f && fabsf(SV.steerSpd - pres[i].sp) < 0.02f;
        if (button(px + i * (pw + u * 2), py, pw, ph, pres[i].n, cur ? C_BLUE : C_GRAY, u * 0.95f)) { SV.steerMul = pres[i].s; SV.gripMul = pres[i].g; SV.steerSpd = pres[i].sp; }
    }
    // ползунки
    float sx = px, sw = W * 0.55f - u * 20, sh = u * 10, sy = py + ph + u * 26;
    SV.steerMul = slider(sx, sy, sw, sh, "РЕЗКОСТЬ РУЛЯ (УГОЛ ПОВОРОТА КОЛЁС)", fmt("%d%%", (int)(SV.steerMul * 100 + 0.5f)), SV.steerMul, 0.5f, 1.8f); sy += u * 30;
    SV.gripMul = slider(sx, sy, sw, sh, "СЦЕПЛЕНИЕ (МЕНЬШЕ — БОЛЬШЕ ЗАНОСА)", fmt("%d%%", (int)(SV.gripMul * 100 + 0.5f)), SV.gripMul, 0.55f, 1.8f); sy += u * 30;
    SV.steerSpd = slider(sx, sy, sw, sh, "СКОРОСТЬ РУЛЯ (ОТКЛИК КНОПОК)", fmt("%d%%", (int)(SV.steerSpd * 100 + 0.5f)), SV.steerSpd, 0.4f, 2.0f); sy += u * 30;
    if (SV.tilt) { SV.tiltSens = slider(sx, sy, sw, sh, "ЧУВСТВИТЕЛЬНОСТЬ НАКЛОНА", fmt("%d%%", (int)(SV.tiltSens * 100 + 0.5f)), SV.tiltSens, 0.4f, 2.0f); sy += u * 30; }
    // переключатели
    float tx = mx + W * 0.58f, tw = W * 0.42f - u * 10, ty = py, th = u * 22;
    if (button(tx, ty, tw, th, SV.laneAssist ? "ПОМОЩЬ ПОЛОСЫ: ВКЛ" : "ПОМОЩЬ ПОЛОСЫ: ВЫКЛ", SV.laneAssist ? C_GREEN : C_GRAY, u * 0.95f)) SV.laneAssist = !SV.laneAssist;
    ty += th + u * 5;
    if (gAccel) { if (button(tx, ty, tw, th, SV.tilt ? "РУЛЬ НАКЛОНОМ: ВКЛ" : "РУЛЬ НАКЛОНОМ: ВЫКЛ", SV.tilt ? C_GREEN : C_GRAY, u * 0.95f)) SV.tilt = !SV.tilt; }
    else button(tx, ty, tw, th, "РУЛЬ НАКЛОНОМ: НЕТ ДАТЧИКА", C_GRAY, u * 0.95f, false);
    ty += th + u * 5;
    if (SV.tilt && gAccel) {
        if (button(tx, ty, tw, th, SV.tiltInv ? "ИНВЕРСИЯ НАКЛОНА: ВКЛ" : "ИНВЕРСИЯ НАКЛОНА: ВЫКЛ", C_GRAY, u * 0.95f)) SV.tiltInv = !SV.tiltInv;
        ty += th + u * 5;
        // индикатор наклона
        float s = accelSteer();
        UI.roundRect(tx, ty, tw, u * 10, u * 3, RGBA(40, 46, 56));
        UI.rect(tx + tw / 2 - 1, ty, 2, u * 10, C_LIGHT);
        UI.circle(tx + tw / 2 + s * tw / 2 * 0.95f, ty + u * 5, u * 5, C_YELLOW, 16);
        ty += u * 15;
    }
    if (button(tx, ty, tw, th, SV.sound ? "ЗВУК: ВКЛ" : "ЗВУК: ВЫКЛ", C_GRAY, u * 0.95f)) { SV.sound = !SV.sound; SY.muted = !SV.sound; }
    ty += th + u * 10;
    // подсказка с цифрами
    UI.text(tx, ty, (std::string("МАШИНА: ") + PATROL[SV.car].name).c_str(), u * 0.9f, RGBA(150, 200, 255)); ty += u * 11;
    UI.text(tx, ty, fmt("РАДИУС ПОВОРОТА НА 60 КМ/Ч: %d М", (int)(radiusAt(60) + 0.5f)).c_str(), u * 0.9f, C_LIGHT); ty += u * 10;
    UI.text(tx, ty, fmt("РАДИУС ПОВОРОТА НА 100 КМ/Ч: %d М", (int)(radiusAt(100) + 0.5f)).c_str(), u * 0.9f, C_LIGHT); ty += u * 10;
    if (SV.gripMul < 0.85f) UI.text(tx, ty, "ВНИМАНИЕ: МАШИНУ БУДЕТ ЗАНОСИТЬ", u * 0.9f, C_YELLOW);
    if (button(mx + u * 10, mt + H - u * 32, u * 110, u * 24, "СБРОС", RGBA(110, 40, 40), u * 1.1f)) { SV.steerMul = 1; SV.gripMul = 1; SV.steerSpd = 1; SV.laneAssist = false; SV.tiltSens = 1; }
    if (button(mx + W - u * 130, mt + H - u * 32, u * 120, u * 24, "ГОТОВО", C_BLUE, u * 1.2f) || gBackPressed) { gBackPressed = false; saveGame(); gScreen = gSettingsReturn; }
    SY.engVol = gSettingsReturn == SC_MENU ? 0.3f : 0; SY.siren = 0; SY.screech = 0; SY.wind = 0;
}
static void drawSummary(float dt) {
    float u = U();
    drawMenuScene(dt);
    UI.rect(0, 0, SW, SH, RGBA(0, 0, 0, 160));
    float mx = std::max(SW * 0.08f, 16.0f), mt = SH * 0.06f;
    float W = SW - 2 * mx, H = SH - 2 * mt;
    panel(mx, mt, W, H, C_DARK);
    UI.text(SW / 2, mt + u * 8, "ИТОГИ СМЕНЫ", u * 1.8f, C_WHITE, 1);
    float y = mt + u * 32, x1 = mx + u * 14, x2 = mx + W * 0.52f;
    auto row = [&](float x, float& yy, const char* l, const std::string& v, SDL_Color c) { UI.text(x, yy, l, u * 1.0f, C_LIGHT); UI.text(x + W * 0.36f, yy, v.c_str(), u * 1.0f, c, 2); yy += u * 12; };
    float ya = y, yb = y;
    row(x1, ya, "ПРОВЕРЕНО МАШИН:", fmt("%d", SHF.checks), C_WHITE);
    row(x1, ya, "ВЕРНЫХ РЕШЕНИЙ:", fmt("%d", SHF.correct), RGBA(120, 255, 140));
    row(x1, ya, "ОШИБОК:", fmt("%d", SHF.wrong), SHF.wrong ? RGBA(255, 120, 100) : C_WHITE);
    row(x1, ya, "ШТРАФОВ:", fmt("%d НА %d ₽", SHF.fines, SHF.finesSum), C_WHITE);
    row(x1, ya, "ЗАДЕРЖАНО:", fmt("%d", SHF.detains), C_WHITE);
    row(x1, ya, "ПОГОНЬ / УСПЕШНЫХ:", fmt("%d / %d", SHF.chases, SHF.chaseWins), C_WHITE);
    row(x1, ya, "ОФОРМЛЕНО ДТП:", fmt("%d", SHF.accidents), C_WHITE);
    row(x2, yb, "ЗАРПЛАТА:", fmt("%d ₽", (int)SHF.lastCamMin), C_YELLOW);
    row(x2, yb, "ПРЕМИИ И ЗАДАНИЯ:", fmt("%d ₽", SHF.bonus), C_YELLOW);
    row(x2, yb, "ДОХОД С КАМЕР:", fmt("%d ₽", SHF.camIncome), C_YELLOW);
    row(x2, yb, "ТОПЛИВО:", fmt("-%d ₽", SHF.fuelSpent), SHF.fuelSpent ? RGBA(255, 160, 120) : C_WHITE);
    row(x2, yb, "ИЗМЕНЕНИЕ СЧЁТА:", fmt("%+d ₽", SHF.startMoney), SHF.startMoney >= 0 ? RGBA(120, 255, 140) : RGBA(255, 120, 100));
    row(x2, yb, "РЕПУТАЦИЯ:", fmt("%+d (ВСЕГО %d)", SHF.repDelta, SV.rep), C_WHITE);
    y = std::max(ya, yb) + u * 6;
    for (int i = 0; i < 3; i++) { UI.text(x1, y, (std::string(SHF.tasks[i].done ? "[X] " : "[ ] ") + taskText(SHF.tasks[i])).c_str(), u * 1.0f, SHF.tasks[i].done ? RGBA(120, 255, 140) : RGBA(170, 170, 180)); y += u * 11; }
    int rk = rankOf(SV.rep);
    if (rk > SHF.startRank) { y += u * 4; UI.text(SW / 2, y, (std::string("ПОВЫШЕНИЕ! ПРИСВОЕНО ЗВАНИЕ: ") + RANKS[rk]).c_str(), u * 1.3f, C_YELLOW, 1, true); }
    if (button(SW / 2 - u * 70, mt + H - u * 34, u * 140, u * 26, "В ГЛАВНОЕ МЕНЮ", C_BLUE, u * 1.2f) || gBackPressed) { gBackPressed = false; clearWorldActors(); gScreen = SC_MENU; }
}
static void drawHelp() {
    float u = U();
    UI.rect(0, 0, SW, SH, RGBA(12, 16, 24, 250));
    float mx = std::max(SW * 0.05f, 16.0f), mt = SH * 0.05f;
    UI.text(mx, mt, "ПАМЯТКА ИНСПЕКТОРА", u * 1.8f, C_WHITE);
    float colW = (SW - 2 * mx - u * 10) / 2;
    const char* left =
        "ЗАДЕРЖАНИЕ: ПОДДЕЛЬНОЕ УДОСТОВЕРЕНИЕ (ОШИБКА В ЗАГОЛОВКЕ, НЕТ ГОЛОГРАММЫ, НЕТ В БАЗЕ), НОМЕРА НЕ СОВПАДАЮТ СО СТС, АВТОМОБИЛЬ В УГОНЕ, КОНТРАБАНДА ИЛИ КРАДЕНОЕ, ПОПЫТКА СКРЫТЬСЯ.\n"
        "ЭВАКУАЦИЯ: НЕТ ДЕЙСТВУЮЩИХ ПРАВ — УДОСТОВЕРЕНИЕ ПРОСРОЧЕНО (П. 4В), ЧУЖОЕ (ДРУГОЕ ФОТО И ИМЯ), ЛИШЁН ПРАВ (ВИДНО В БАЗЕ).\n"
        "ШТРАФ: ПРЕВЫШЕНИЕ БОЛЕЕ 10 КМ/Ч (12.9), КРАСНЫЙ (12.12), НЕТ/ПРОСРОЧЕН ОСАГО, ОСАГО НА ДРУГУЮ МАШИНУ ИЛИ ВОДИТЕЛЬ НЕ ВПИСАН (12.37), НЕ ПРИСТЁГНУТ (12.6 — РЕМНЯ НЕТ НА ФОТО ВОДИТЕЛЯ), ТЕЛЕФОН У УХА (12.36.1), СТЁКЛА ТЕМНЕЕ 70% (12.5), ОБОЧИНА (12.15), БЕЗ ПОВОРОТНИКА (12.14), БЕЗ ФАР (12.20). ОТМЕТЬ ВСЕ НАРУШЕННЫЕ СТАТЬИ.\n"
        "ПРЕДУПРЕЖДЕНИЕ: ПРЕВЫШЕНИЕ ДО 10 КМ/Ч БЕЗ ДРУГИХ НАРУШЕНИЙ.\n"
        "ОТПУСТИТЬ: ВСЁ В ПОРЯДКЕ. СОБСТВЕННИК В СТС МОЖЕТ БЫТЬ ДРУГИМ — ЭТО НЕ НАРУШЕНИЕ.\n"
        "МОДЕЛИ МАШИН (SKETCHFAB.COM, УПРОЩЕНЫ ДЛЯ ИГРЫ): «TOYOTA CAMRY 2020» — ITSDIYOR, CC-BY-4.0; «FERRARI F40 MODIFIED» — VTDAT23, CC-BY-4.0; «JEEP GRAND CHEROKEE TRACKHAWK» — DAVID_HOLIDAY, CC-BY-4.0; «TOYOTA FORTUNER 2021» — ASADAWUT.KAEWMA, CC-BY-4.0; «2011 DACIA (RENAULT) DUSTER» — RAZOR24, CC-BY-4.0; «2022 TOYOTA VELLFIRE» — BHP3D, CC-BY-4.0; «TOYOTA LAND CRUISER J200 2017» — DAVID_HOLIDAY, CC-BY-4.0; "
        "«TOYOTA CELICA GT-FOUR (ST205)» — GT CARS: HYPERSPEED, CC-BY-4.0; «2021 RAM 1500 TRX» — OUTLAW GAMES, CC-BY-NC-4.0; «NISSAN GTR R35 NISMO» — DRIVER-FIRE, CC-BY-4.0; "
        "«2025 BMW M4 COMPETITION», «2018 FORD MUSTANG COBRA JET» И «2011 MAZDA RX-8 SPIRIT R» — DDIAZ DESIGN, CC-BY-NC-SA-4.0; «2022 LEXUS RX 350» — ACTSOFDOGE, «DAEWOO MATIZ» — NYRANAROD, SKETCHFAB STANDARD.";
    const char* right =
        "УПРАВЛЕНИЕ: СЛЕВА — РУЛЬ, СПРАВА — ГАЗ И ТОРМОЗ (ДОЛГО ДЕРЖАТЬ ТОРМОЗ = ЗАДНИЙ ХОД). МОЖНО ЖАТЬ ОДНОВРЕМЕННО.\n"
        "МИГАЛКА ВКЛЮЧАЕТ СВЕТ И СИРЕНУ — МАШИНЫ УСТУПАЮТ ДОРОГУ И ЧАЩЕ ПОДЧИНЯЮТСЯ. «ГУДОК» — ГУДОК СГУ: МАШИНА ВПЕРЕДИ УЙДЁТ ВПРАВО И ПРОПУСТИТ. ДОХОД ЗАВИСИТ ОТ ТРАФИКА В ЗОНЕ: ЧЕМ ПЛОТНЕЕ ПОТОК (ЧАС ПИК, ЗАПАДНАЯ ТРАССА), ТЕМ БОЛЬШЕ ПЛАТЯТ.\n"
        "ТРЕБОВАТЬ (НА ХОДУ) ИЛИ ЖЕЗЛ (СТОЯ) — ОСТАНОВИТЬ МАШИНУ В ЖЁЛТОЙ РАМКЕ. РАДАР ПОКАЗЫВАЕТ СКОРОСТЬ МАШИНЫ ВПЕРЕДИ.\n"
        "ПОСТ ДПС НА ТРАССЕ: МАШИНЫ СБРАСЫВАЮТ ДО 40. ВСТАНЬ В КАРМАН У ЗДАНИЯ И ОСТАНАВЛИВАЙ ЖЕЗЛОМ. ПО РАЦИИ СООБЩАТ О РАЗЫСКИВАЕМОМ — НАЙДИ ЕГО В ПОТОКЕ ПО ОПИСАНИЮ. «ШЛАГБАУМ» ПЕРЕКРЫВАЕТ ДОРОГУ — БЕГЛЕЦ НЕ ПРОЕДЕТ.\n"
        "ТОПЛИВО ТРАТИТСЯ НА ХОДУ (БЫСТРЕЕ НА БОЛЬШОЙ СКОРОСТИ). ЗАПРАВКИ «А» — У ТРАСС: ВСТАНЬ У КОЛОНКИ ПОД НАВЕСОМ И НАЖМИ «ЗАПРАВИТЬСЯ». КОНЧИЛСЯ БЕНЗИН — ВЫЗОВИ ТОПЛИВОЗАПРАВЩИК.\n"
        "ПОГОНЯ: ДЕРЖИСЬ БЛИЖЕ И ТОЛКАЙ БЕГЛЕЦА, ПОКА НЕ ЗАПОЛНИТСЯ ШКАЛА. ВЫЗОВИ ПОМОЩЬ. БЛОКПОСТ — ТОЛЬКО ДЛЯ МАШИН В РОЗЫСКЕ И СТРИТРЕЙСЕРОВ. ОТСТАНЕШЬ — ПРОВАЛ. НА МОЩНОЙ МАШИНЕ БЕГЛЕЦ БЫСТРЕЕ. СИЛЬНЫЙ УДАР В УГОЛ МОЖЕТ ЕГО РАЗВЕРНУТЬ, А НА СКОРОСТИ ОН И САМ МОЖЕТ РАЗБИТЬСЯ.\n"
        "ДТП: ЕДЬ ПО СТРЕЛКЕ, ОСТАНОВИСЬ У МЕСТА И ОФОРМИ. ВИНОВНИК: ВЪЕХАЛ СЗАДИ — 12.15, ПЕРЕСТРОИЛСЯ В ДРУГУЮ МАШИНУ — 12.14, НЕ ПРОПУСТИЛ МАШИНУ СПРАВА БЕЗ СВЕТОФОРА — 12.13, ПРОЕХАЛ НА КРАСНЫЙ — 12.12. ПРОВЕРЯЙ АЛКОТЕСТЕРОМ, ВЫЗЫВАЙ СКОРУЮ.\n"
        "ПРИДИРКИ К ЧЕСТНЫМ ВОДИТЕЛЯМ ВЕДУТ К ЖАЛОБАМ И ШТРАФАМ. ЗВАНИЯ ОТКРЫВАЮТ НОВЫЕ УЧАСТКИ И МАШИНЫ.\n"
        "ГЕЙМПАД PS5: СТИК — РУЛЬ, R2/L2 — ГАЗ/ТОРМОЗ, КРЕСТ — ТРЕБОВАТЬ, КРУГ — ГУДОК, КВАДРАТ — МИГАЛКА, ТРЕУГОЛЬНИК — ВИД, L1 — ЦЕЛЬ, R1 — РАДИО. ЧУВСТВИТЕЛЬНОСТЬ — В НАСТРОЙКАХ.";
    UI.textBox(mx, mt + u * 22, colW, left, u * 0.86f, C_LIGHT);
    UI.textBox(mx + colW + u * 10, mt + u * 22, colW, right, u * 0.8f, C_LIGHT);
    if (button(SW / 2 - u * 60, SH - mt - u * 26, u * 120, u * 24, "ПОНЯТНО", C_BLUE, u * 1.2f) || gBackPressed) { gBackPressed = false; gScreen = gHelpReturn; }
}

// ---------------------------------------------------------------------
//  Главный цикл
// ---------------------------------------------------------------------
static void handleEvent(const SDL_Event& e) {
    switch (e.type) {
        case SDL_QUIT: saveGame(); gQuit = true; break;
        case SDL_APP_WILLENTERBACKGROUND: case SDL_APP_TERMINATING: case SDL_APP_DIDENTERBACKGROUND:
            saveGame();
            if (gScreen == SC_DRIVE) gScreen = SC_PAUSE;
            if (gAudio) SDL_PauseAudioDevice(gAudio, 1);
            FINGERS.clear();
            gBackground = true;
            break;
        case SDL_APP_DIDENTERFOREGROUND: if (gAudio) SDL_PauseAudioDevice(gAudio, 0); FINGERS.clear(); gBackground = false; break;
        case SDL_RENDER_DEVICE_RESET:
            // контекст GPU потерян — пересоздаём атлас из копии в памяти
            if (atlasTex) SDL_DestroyTexture(atlasTex);
            if (atlasTexAdd) SDL_DestroyTexture(atlasTexAdd);
            createAtlasTextures();
            break;
        case SDL_WINDOWEVENT:
            if (e.window.event == SDL_WINDOWEVENT_SIZE_CHANGED || e.window.event == SDL_WINDOWEVENT_RESIZED) { int w, h; SDL_GetRendererOutputSize(gRen, &w, &h); SW = w; SH = h; DROPS.clear(); }
            if (e.window.event == SDL_WINDOWEVENT_FOCUS_LOST && gScreen == SC_DRIVE) { /* не ставим на паузу на ПК */ }
            break;
        case SDL_FINGERDOWN: {
            Finger f; f.id = e.tfinger.fingerId; f.x = e.tfinger.x * SW; f.y = e.tfinger.y * SH;
            FINGERS.push_back(f); TAPS.push_back({f.x, f.y, false});
        } break;
        case SDL_FINGERMOTION:
            for (Finger& f : FINGERS) if (f.id == e.tfinger.fingerId) { f.x = e.tfinger.x * SW; f.y = e.tfinger.y * SH; }
            break;
        case SDL_FINGERUP:
            for (size_t i = 0; i < FINGERS.size(); i++) if (FINGERS[i].id == e.tfinger.fingerId) { FINGERS.erase(FINGERS.begin() + i); break; }
            break;
        case SDL_MOUSEBUTTONDOWN:
            if (e.button.which == SDL_TOUCH_MOUSEID) break;
            { Finger f; f.id = (SDL_FingerID)-777; f.x = (float)e.button.x * SW / std::max(1, SW); f.y = (float)e.button.y;
              int ww, wh; SDL_GetWindowSize(gWin, &ww, &wh); f.x = e.button.x * (float)SW / ww; f.y = e.button.y * (float)SH / wh;
              FINGERS.push_back(f); TAPS.push_back({f.x, f.y, false}); }
            break;
        case SDL_MOUSEMOTION:
            if (e.motion.which == SDL_TOUCH_MOUSEID) break;
            { int ww, wh; SDL_GetWindowSize(gWin, &ww, &wh); for (Finger& f : FINGERS) if (f.id == (SDL_FingerID)-777) { f.x = e.motion.x * (float)SW / ww; f.y = e.motion.y * (float)SH / wh; } }
            break;
        case SDL_MOUSEBUTTONUP:
            if (e.button.which == SDL_TOUCH_MOUSEID) break;
            for (size_t i = 0; i < FINGERS.size(); i++) if (FINGERS[i].id == (SDL_FingerID)-777) { FINGERS.erase(FINGERS.begin() + i); break; }
            break;
        case SDL_KEYDOWN:
            gKeys[e.key.keysym.scancode] = true;
            if (gScreen == SC_INTRO && !e.key.repeat) gIntroSkip = true;
            if (e.key.keysym.sym == SDLK_AC_BACK || e.key.keysym.sym == SDLK_ESCAPE) gBackPressed = true;
            if (gScreen == SC_DRIVE && !e.key.repeat) {
                if (e.key.keysym.sym == SDLK_f) { PL.flash = !PL.flash; PL.siren = PL.flash; }
                if (e.key.keysym.sym == SDLK_e) demandStop();
                if (e.key.keysym.sym == SDLK_c) { gCamMode = 1 - gCamMode; updateCamera(0, true); }
                if (e.key.keysym.sym == SDLK_h && gHornT <= 0) { sfx(SFX_QUACK, 0.9f); gHornT = 1.25f; }
            }
            break;
        case SDL_KEYUP: gKeys[e.key.keysym.scancode] = false; break;
        case SDL_CONTROLLERDEVICEADDED: padOpen(e.cdevice.which); break;
        case SDL_CONTROLLERDEVICEREMOVED:
            if (gPad && SDL_JoystickInstanceID(SDL_GameControllerGetJoystick(gPad)) == e.cdevice.which) {
                SDL_GameControllerClose(gPad); gPad = nullptr; gCurHeld = false;
                for (size_t i = 0; i < FINGERS.size(); i++) if (FINGERS[i].id == (SDL_FingerID)-888) { FINGERS.erase(FINGERS.begin() + i); break; }
                toast("ГЕЙМПАД ОТКЛЮЧЁН", 0, 2);
                for (int i = 0; i < SDL_NumJoysticks(); i++) padOpen(i);   // другой, если есть
            }
            break;
        case SDL_CONTROLLERBUTTONDOWN: {
            if (!gPad || SDL_JoystickInstanceID(SDL_GameControllerGetJoystick(gPad)) != e.cbutton.which) break;
            int b = e.cbutton.button;
            if (gScreen == SC_INTRO) { gIntroSkip = true; break; }
            bool drive = gScreen == SC_DRIVE;
            bool cursorTap = !drive ? (b == SDL_CONTROLLER_BUTTON_A) : (b == SDL_CONTROLLER_BUTTON_RIGHTSTICK);
            if (cursorTap) {
                if (gCurX < 0) { gCurX = SW * 0.5f; gCurY = SH * 0.5f; }
                padTapAt(gCurX, gCurY); gCurShowT = 4;
                Finger f; f.id = (SDL_FingerID)-888; f.x = gCurX; f.y = gCurY; FINGERS.push_back(f); gCurHeld = true;
                break;
            }
            if (b == SDL_CONTROLLER_BUTTON_START) { gBackPressed = true; break; }                 // пауза / назад
            if (!drive) {
                if (b == SDL_CONTROLLER_BUTTON_B) gBackPressed = true;
                break;
            }
            // за рулём
            if (b == SDL_CONTROLLER_BUTTON_A) {
                if (gCtxX >= 0) padTapAt(gCtxX, gCtxY);   // «проверить документы» / «оформить ДТП»
                else demandStop();
            } else if (b == SDL_CONTROLLER_BUTTON_B) {
                if (gHornT <= 0) { sfx(SFX_QUACK, 0.9f); gHornT = 1.25f; }
            } else if (b == SDL_CONTROLLER_BUTTON_X) {
                PL.flash = !PL.flash; PL.siren = PL.flash; sfx(SFX_BEEP, 0.5f, PL.flash ? 1200 : 600);
            } else if (b == SDL_CONTROLLER_BUTTON_Y) {
                gCamMode = 1 - gCamMode; SV.camView = gCamMode; updateCamera(0, true);
            } else if (b == SDL_CONTROLLER_BUTTON_LEFTSHOULDER) {
                // следующая машина-цель: по удалённости, среди тех, кто впереди
                std::vector<std::pair<float, int>> cand;
                V3 f = fwdOf(PL.yaw);
                for (size_t i = 0; i < CARS.size(); i++) {
                    if (!targetable(CARS[i], (int)i)) continue;
                    V3 d = CARS[i].pos - PL.pos; float dd = len(d);
                    bool parked = fabsf(PL.speed) < 1.5f; float cs = dot(d * (1 / dd), f);
                    if (dd < 2 || dd > (parked ? 50.f : 80.f)) continue;
                    if (parked ? (dd > 25 && cs < -0.2f) : cs < 0.45f) continue;   // как при автовыборе: на ходу — только впереди
                    cand.push_back({dd, (int)i});
                }
                std::sort(cand.begin(), cand.end());
                if (!cand.empty()) {
                    size_t k = 0;
                    for (size_t j = 0; j < cand.size(); j++) if (cand[j].second == gTarget) { k = (j + 1) % cand.size(); break; }
                    int bi = cand[k].second; gManualTarget = bi; gManualId = CARS[bi].id; gTarget = bi; sfx(SFX_CLICK);
                }
            } else if (b == SDL_CONTROLLER_BUTTON_RIGHTSHOULDER) {
                if (gRadioPcm.empty()) radioDecode();
                if (gAudio) SDL_LockAudioDevice(gAudio);
                gRadioOn = !gRadioOn;
                if (gAudio) SDL_UnlockAudioDevice(gAudio);
                toast(gRadioOn ? "РАДИО: MACAN - ASPHALT 8" : "РАДИО: ПАУЗА", 0, 1.6f);
            } else if (b == SDL_CONTROLLER_BUTTON_BACK || b == SDL_CONTROLLER_BUTTON_TOUCHPAD) {
                gMapReturn = SC_DRIVE; gScreen = SC_MAP; TOASTS.clear();
            }
        } break;
        case SDL_CONTROLLERBUTTONUP: {
            int b = e.cbutton.button;
            if (gCurHeld && (b == SDL_CONTROLLER_BUTTON_A || b == SDL_CONTROLLER_BUTTON_RIGHTSTICK)) {
                gCurHeld = false;
                for (size_t i = 0; i < FINGERS.size(); i++) if (FINGERS[i].id == (SDL_FingerID)-888) { FINGERS.erase(FINGERS.begin() + i); break; }
            }
        } break;
    }
}

// геймпад: каждый кадр — руление/педали за рулём, курсор в меню, вибрация и световая панель DualSense
static void padUpdate(float dt) {
    if (!gPad) return;
    bool drive = gScreen == SC_DRIVE;
    // курсор: в меню — левый стик и крестовина, за рулём — правый стик
    float cx = drive ? padAxis(SDL_CONTROLLER_AXIS_RIGHTX) : padAxis(SDL_CONTROLLER_AXIS_LEFTX);
    float cy = drive ? padAxis(SDL_CONTROLLER_AXIS_RIGHTY) : padAxis(SDL_CONTROLLER_AXIS_LEFTY);
    if (!drive) {
        if (padBtn(SDL_CONTROLLER_BUTTON_DPAD_LEFT)) cx = -0.6f;
        if (padBtn(SDL_CONTROLLER_BUTTON_DPAD_RIGHT)) cx = 0.6f;
        if (padBtn(SDL_CONTROLLER_BUTTON_DPAD_UP)) cy = -0.6f;
        if (padBtn(SDL_CONTROLLER_BUTTON_DPAD_DOWN)) cy = 0.6f;
    }
    float m = sqrtf(cx * cx + cy * cy);
    if (m > 0.18f) {
        if (gCurX < 0) { gCurX = SW * 0.5f; gCurY = SH * 0.5f; }
        float k = (m - 0.18f) / 0.82f, sp = SH * (0.25f + 1.6f * k * k) * SV.padCursor * dt / m;
        gCurX = clampf(gCurX + cx * sp, 0, (float)SW - 1); gCurY = clampf(gCurY + cy * sp, 0, (float)SH - 1);
        gCurShowT = drive ? 3.f : 1e9f;
        for (Finger& f : FINGERS) if (f.id == (SDL_FingerID)-888) { f.x = gCurX; f.y = gCurY; }
    }
    if (!drive && gCurShowT < 5) { gCurShowT = 1e9f; if (gCurX < 0) { gCurX = SW * 0.5f; gCurY = SH * 0.5f; } }
    gCurShowT -= dt;
    // руль и педали
    if (drive) {
        float sx = padAxis(SDL_CONTROLLER_AXIS_LEFTX);
        if (padBtn(SDL_CONTROLLER_BUTTON_DPAD_LEFT)) sx = -1;
        if (padBtn(SDL_CONTROLLER_BUTTON_DPAD_RIGHT)) sx = 1;
        float st = padStickToSteer(sx);
        if (st != 0) gIn.steer = st;
        float rt = padTrigger(padAxis(SDL_CONTROLLER_AXIS_TRIGGERRIGHT)), lt = padTrigger(padAxis(SDL_CONTROLLER_AXIS_TRIGGERLEFT));
        if (rt > 0) gIn.throttle = std::max(gIn.throttle, rt);
        if (lt > 0) gIn.brake = std::max(gIn.brake, lt);
        // вибрация: удар (резкая потеря скорости) и тряска по бездорожью
        float dv = gPadPrevSpeed - fabsf(PL.speed);
        if (!SV.padRumble) {}
        else if (dv > 2.5f && gPadRumbleT <= 0) { padRumble(clampf(dv / 10, 0.3f, 1), clampf(dv / 14, 0.2f, 1), 250 + (int)(dv * 25)); gPadRumbleT = 0.25f; }
        else if (PL.offroad && fabsf(PL.speed) > 4 && gPadRumbleT <= 0) { padRumble(0.12f, 0.05f, 120); gPadRumbleT = 0.1f; }
    }
    gPadPrevSpeed = fabsf(PL.speed);
    gPadRumbleT -= dt;
#if SDL_VERSION_ATLEAST(2, 0, 14)
    // световая панель DualSense: мигалка — красный/синий, иначе — спокойный синий
    static float ledT = 0; ledT -= dt;
    if (ledT <= 0) {
        ledT = 0.06f;
        if (!SV.padLed) SDL_GameControllerSetLED(gPad, 0, 0, 0);
        else if (PL.flash && drive) { bool ph = fmodf(gTime, 0.5f) < 0.25f; SDL_GameControllerSetLED(gPad, ph ? 255 : 0, 0, ph ? 0 : 255); }
        else SDL_GameControllerSetLED(gPad, 0, 30, 120);
    }
#endif
}
static void padDrawCursor() {
    if (!gPad || gCurX < 0 || gCurShowT <= 0) return;
    float u = U();
    UI.circle(gCurX + u, gCurY + u, u * 9, RGBA(0, 0, 0, 90), 20);
    UI.circle(gCurX, gCurY, u * 9, gCurHeld ? RGBA(255, 210, 60, 235) : RGBA(255, 255, 255, 230), 20);
    UI.circle(gCurX, gCurY, u * 6.8f, RGBA(30, 95, 200, 235), 20);
    UI.circle(gCurX, gCurY, u * 2, RGBA(255, 255, 255, 255), 10);
}

static void frame(float dt) {
    gTime += dt;
    SDL_SetRenderDrawColor(gRen, 0, 0, 0, 255);
    SDL_RenderClear(gRen);
    gRadioMuffle = gCamMode == 1 ? 0.f : 1.f;
    if (!SHF.active && gRadioOn) gRadioOn = false;   // смена закончилась — радио выключается
    gCtxX = -1;
    if (gScreen != SC_DRIVE) padUpdate(dt);
    switch (gScreen) {
        case SC_INTRO: drawIntro(dt); break;
        case SC_MENU: drawMenu(dt); break;
        case SC_EXITCONFIRM: drawExitConfirm(dt); break;
        case SC_SETTINGS: drawSettings(dt); break;
        case SC_SHIFTSTART: drawShiftStart(dt); break;
        case SC_GARAGE: drawGarage(dt); break;
        case SC_HELP: drawHelp(); break;
        case SC_MAP: drawMap(); for (size_t i = 0; i < TOASTS.size();) { TOASTS[i].t -= dt; if (TOASTS[i].t <= 0) TOASTS.erase(TOASTS.begin() + i); else i++; } break;
        case SC_SUMMARY: drawSummary(dt); break;
        case SC_DRIVE: {
            // физика подшагами: при низком FPS игра не замедляется
            { int n = (int)ceilf(dt / (1.0f / 30)); if (n < 1) n = 1; if (n > 4) n = 4; for (int k = 0; k < n && gScreen == SC_DRIVE; k++) updateDrive(dt / n); }
            if (gScreen != SC_DRIVE) { updateCamera(dt, false); drawWorldScene(dt, true, gCamMode == 1); break; }
            updateCamera(dt, false);
            drawWorldScene(dt, true, gCamMode == 1);
            drawRain(dt, gCamMode == 1); drawSnowfall(dt);
            if (gCamMode == 1) drawCockpitOverlay();
            drawDriveHUD();
            if (gKeys[SDL_SCANCODE_LEFT] || gKeys[SDL_SCANCODE_A]) gIn.steer = -1;
            if (gKeys[SDL_SCANCODE_RIGHT] || gKeys[SDL_SCANCODE_D]) gIn.steer = 1;
            if (gKeys[SDL_SCANCODE_UP] || gKeys[SDL_SCANCODE_W]) gIn.throttle = 1;
            if (gKeys[SDL_SCANCODE_DOWN] || gKeys[SDL_SCANCODE_S] || gKeys[SDL_SCANCODE_SPACE]) gIn.brake = 1;
            if (gKeys[SDL_SCANCODE_RETURN] && gInspect >= 0 && fabsf(PL.speed) < 2) { gScreen = SC_DOCS; PL.speed = 0; gKeys[SDL_SCANCODE_RETURN] = false; }
            padUpdate(dt);
        } break;
        case SC_DOCS: case SC_DECIDE: case SC_RESULT: case SC_PAUSE: {
            SY.engLoad = 0; SY.screech = 0; SY.wind = 0; SY.siren = 0;
            if (gScreen != SC_PAUSE && (gInspect < 0 || gInspect >= (int)CARS.size() || !CARS[gInspect].alive || CARS[gInspect].caseIdx < 0) && gScreen != SC_RESULT) { gScreen = SC_DRIVE; break; }
            updateCamera(0, false);
            drawWorldScene(dt, true, gCamMode == 1);
            if (gCamMode == 1) drawCockpitOverlay();
            if (gScreen == SC_DOCS) drawDocs(dt);
            else if (gScreen == SC_DECIDE) drawDecide();
            else if (gScreen == SC_RESULT) drawResult();
            else drawPause();
        } break;
        case SC_ACCIDENT:
            SY.siren = 0; SY.engLoad = 0;
            if (!ACC.active) { gScreen = SC_DRIVE; break; }
            updateCamera(0, false);
            drawWorldScene(dt, true, gCamMode == 1);
            drawAccidentScreen(dt);
            break;
        case SC_TRUNK:
            SY.siren = 0; SY.engLoad = 0;
            if (gInspect < 0 || !CARS[gInspect].alive || CARS[gInspect].caseIdx < 0) { gScreen = SC_DRIVE; break; }
            drawTrunkScreen(dt);
            break;
    }
    if (gFadeIn > 0) { UI.rect(0, 0, SW, SH, RGBA(0, 0, 0, (int)(255 * clampf(gFadeIn / 0.6f, 0, 1)))); gFadeIn -= dt; }   // плавное появление после заставки
    if (gScreen != SC_INTRO) padDrawCursor();
    UI.flush();
    TAPS.clear();
    gBackPressed = false;
}

#ifdef GAISHNIK_TEST
static void testHook(int frameNo, float& dt);
#endif

int main(int argc, char** argv) {
    (void)argc; (void)argv;
    SDL_SetHint(SDL_HINT_ORIENTATIONS, "LandscapeLeft LandscapeRight");
    SDL_SetHint(SDL_HINT_ANDROID_TRAP_BACK_BUTTON, "1");
    SDL_SetHint(SDL_HINT_TOUCH_MOUSE_EVENTS, "0");
    SDL_SetHint(SDL_HINT_MOUSE_TOUCH_EVENTS, "0");
    SDL_SetHint(SDL_HINT_RENDER_SCALE_QUALITY, "0");
    SDL_SetHint(SDL_HINT_ACCELEROMETER_AS_JOYSTICK, "1");
    if (SDL_Init(SDL_INIT_VIDEO | SDL_INIT_AUDIO | SDL_INIT_EVENTS) != 0) { SDL_Log("SDL_Init: %s", SDL_GetError()); return 1; }
#ifdef __ANDROID__
    gWin = SDL_CreateWindow("Инспектор ДПС", 0, 0, 0, 0, SDL_WINDOW_FULLSCREEN_DESKTOP | SDL_WINDOW_ALLOW_HIGHDPI);
#else
    gWin = SDL_CreateWindow("Инспектор ДПС", SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED, 1280, 720, SDL_WINDOW_RESIZABLE | SDL_WINDOW_ALLOW_HIGHDPI);
#endif
    if (!gWin) { SDL_Log("window: %s", SDL_GetError()); return 1; }
    gRen = SDL_CreateRenderer(gWin, -1, SDL_RENDERER_ACCELERATED | SDL_RENDERER_PRESENTVSYNC);
    if (!gRen) gRen = SDL_CreateRenderer(gWin, -1, SDL_RENDERER_SOFTWARE);
    if (!gRen) { SDL_Log("renderer: %s", SDL_GetError()); return 1; }
    SDL_GetRendererOutputSize(gRen, &SW, &SH);
    if (SW < SH) std::swap(SW, SH);
    SDL_GetRendererOutputSize(gRen, &SW, &SH);
    buildAtlas(); createAtlasTextures();
    loadAllModels();
    {   // гудок: встроенная запись
        std::vector<uint8_t> raw = b64decode(HORN_PCM_B64);
        gHornPcm.resize(raw.size() / 2);
        if (!raw.empty()) memcpy(gHornPcm.data(), raw.data(), gHornPcm.size() * 2);
        gHornRate = (float)HORN_PCM_RATE;
    }
    CAR_CULL = -1;
    buildRoads(); buildScenery();
    for (int i = 0; i < 4; i++) platePixels(i, i < 2 ? "А000АА" : "А0166", 66, i >= 2);
    applyPlayerPlate(SV.plate);
    // путь сохранения
#ifdef __ANDROID__
    const char* ip = SDL_AndroidGetInternalStoragePath();
    gSavePath = std::string(ip ? ip : ".") + "/gaishnik_save.txt";
#else
    char* bp = SDL_GetBasePath();
    gSavePath = std::string(bp ? bp : "./") + "gaishnik_save.txt";
    if (bp) SDL_free(bp);
#endif
    loadGame();
#ifdef GAISHNIK_TEST
    if (getenv("INTRO")) startIntro();
#else
    startIntro();   // заставка при каждом запуске
#endif
    // акселерометр (на Android доступен как джойстик) — для руления наклоном
    // геймпады: DualSense/DualShock с вибрацией и подсветкой
#ifdef SDL_HINT_JOYSTICK_HIDAPI_PS5_RUMBLE
    SDL_SetHint(SDL_HINT_JOYSTICK_HIDAPI_PS5_RUMBLE, "1");
#endif
#ifdef SDL_HINT_JOYSTICK_HIDAPI_PS4_RUMBLE
    SDL_SetHint(SDL_HINT_JOYSTICK_HIDAPI_PS4_RUMBLE, "1");
#endif
    SDL_SetHint(SDL_HINT_JOYSTICK_ALLOW_BACKGROUND_EVENTS, "0");
    if (SDL_InitSubSystem(SDL_INIT_GAMECONTROLLER) == 0) for (int i = 0; i < SDL_NumJoysticks(); i++) padOpen(i);
    if (SDL_InitSubSystem(SDL_INIT_JOYSTICK) == 0) {
        for (int i = 0; i < SDL_NumJoysticks(); i++) {
            const char* nm = SDL_JoystickNameForIndex(i);
            if (nm && strstr(nm, "ccelerometer")) { gAccel = SDL_JoystickOpen(i); break; }
        }
    }
    initAudio();
    SY.muted = !SV.sound;
    gCamMode = SV.camView;
    playerSetCar();
    Uint64 prev = SDL_GetPerformanceCounter();
    int frameNo = 0;
    while (!gQuit) {
        SDL_Event e;
        while (SDL_PollEvent(&e)) handleEvent(e);
        if (gBackground) {
            // в фоне не рисуем — ждём возвращения
            if (SDL_WaitEventTimeout(&e, 200)) handleEvent(e);
            prev = SDL_GetPerformanceCounter();
            continue;
        }
        Uint64 now = SDL_GetPerformanceCounter();
        float dt = (float)((now - prev) / (double)SDL_GetPerformanceFrequency());
        prev = now;
        if (dt > 0.12f) dt = 0.12f;
        if (dt < 0.001f) dt = 0.001f;
#ifdef GAISHNIK_TEST
        testHook(frameNo, dt);
#endif
        frame(dt);
        SDL_RenderPresent(gRen);
        frameNo++;
        (void)frameNo;
    }
    saveGame();
    if (gAudio) SDL_CloseAudioDevice(gAudio);
    SDL_DestroyRenderer(gRen); SDL_DestroyWindow(gWin);
    SDL_Quit();
    return 0;
}
